-- Task 46: the e-service catalogue for a database that has no seed (prod, Task 5): the 13 request types with their forms,
-- steps, each step's role and the effect of the last step. Generated from content/seed.json: the texts are identical, so
-- the translation keys match (tests/integration/test_service_honesty.py compares them). A database that already has the
-- types gets the same content; whether a type is offered (enabled) is the administrator's flag and is not touched here,
-- except in a demo database (it has the demo logins), where every type stays open as before.
ON CONFLICT(code) DO UPDATE SET seq=excluded.seq, category=excluded.category, name=excluded.name, icon=excluded.icon, sla_hours=excluded.sla_hours, document=excluded.document, document_en=excluded.document_en, prefix=excluded.prefix, description=excluded.description, needs=excluded.needs, outcome=excluded.outcome, privacy=excluded.privacy, fields=excluded.fields, attachments=excluded.attachments, steps=excluded.steps, answer=excluded.answer, popular=excluded.popular, step_roles=excluded.step_roles, effect=excluded.effect;
UPDATE request_types SET enabled=1 WHERE EXISTS (SELECT 1 FROM settings WHERE key='demo_logins');
