INSERT INTO request_types(code, seq, category, name, icon, sla_hours, document, document_en, prefix, description, needs, outcome, privacy, fields, attachments, steps, answer, popular, step_roles, effect) VALUES
('enrollment_certificate', 0, 'docs', 'Təhsil aldığını təsdiq edən arayış', 'file', 24, 'ARAYIŞ', 'CERTIFICATE OF ENROLMENT', 'ARY', 'Hərbi komissarlıq, DSMF, bank, səfirlik, iş yeri və digər qurumlar üçün. Mətn seçdiyiniz təyinata uyğun avtomatik hazırlanır.', '["Əlavə sənəd tələb olunmur"]', 'QR kodlu elektron arayış (PDF). İstəsəniz, kağız nüsxə tədris hissəsində hazır olacaq.', '', '[{"name": "purpose", "label": "Arayışın təyinatı", "type": "radio", "required": true, "options": ["Hərbi komissarlıq", "Dövlət Sosial Müdafiə Fondu (DSMF)", "Bank", "Səfirlik / viza", "İş yeri", "ASAN xidmət / dövlət qurumu", "Digər"]}, {"name": "purpose_other", "label": "Təyinatı yazın", "type": "text", "required": true, "show_if": {"purpose": "Digər"}, "placeholder": "Məsələn: təhsil krediti üçün"}, {"name": "org", "label": "Qurumun adı", "type": "text", "placeholder": "Məsələn: Yasamal rayon hərbi komissarlığı", "hint": "İstəyə görə — arayışın mətnində göstəriləcək"}, {"name": "lang", "label": "Arayışın dili", "type": "select", "options": ["Azərbaycan dili", "İngilis dili"], "hint_if": {"purpose": "Səfirlik / viza", "text": "Səfirlik üçün ingilis dilində arayış tövsiyə olunur."}}, {"name": "copies", "label": "Nüsxə sayı", "type": "select", "options": ["1", "2", "3"]}, {"name": "delivery", "label": "Təhvil forması", "type": "radio", "options": ["Elektron (QR kodlu PDF)", "Kağız — tədris hissəsindən götürəcəm"]}]', 'null', '["Tədris hissəsi yoxlayır", "Sənəd hazırlanır və təsdiqlənir"]', '', 1, '["academic_office", "academic_office"]', 'document.issue'),
('transcript', 1, 'docs', 'Akademik göstəricilər haqqında çıxarış (transkript)', 'list', 48, 'AKADEMİK GÖSTƏRİCİLƏR HAQQINDA ÇIXARIŞ', 'ACADEMIC TRANSCRIPT', 'TRN', 'Keçilmiş fənlər, kreditlər və ballar haqqında rəsmi çıxarış — mübadilə proqramı, magistratura və iş yeri üçün.', '["Əlavə sənəd tələb olunmur"]', 'QR kodlu elektron transkript (Azərbaycan və ya ingilis dilində).', '', '[{"name": "purpose", "label": "Təyinatı", "type": "select", "required": true, "options": ["Mübadilə proqramı (Erasmus+ və s.)", "Magistraturaya qəbul", "İş yeri", "Təqaüd müsabiqəsi", "Digər"]}, {"name": "lang", "label": "Dil", "type": "select", "options": ["Azərbaycan dili", "İngilis dili"]}, {"name": "scope", "label": "Əhatə", "type": "select", "options": ["Bütün semestrlər", "Son semestr"]}, {"name": "delivery", "label": "Təhvil forması", "type": "radio", "options": ["Elektron (QR kodlu PDF)", "Kağız — tədris hissəsindən götürəcəm"]}]', 'null', '["Tədris hissəsi yoxlayır", "Sənəd hazırlanır və təsdiqlənir"]', '', 1, '["academic_office", "academic_office"]', 'document.issue'),
('student_card', 2, 'docs', 'Tələbə biletinin bərpası', 'idcard', 72, NULL, NULL, 'TBB', 'Tələbə bileti itdikdə, zədələndikdə və ya məlumatlar dəyişdikdə.', '["3×4 ölçülü fotoşəkil"]', 'Yeni bilet hazır olanda bildiriş gələcək; bileti dekanlıqdan götürəcəksiniz.', '', '[{"name": "reason", "label": "Səbəb", "type": "radio", "required": true, "options": ["İtib", "Zədələnib", "Şəxsi məlumatlar dəyişib"]}, {"name": "details", "label": "Əlavə qeyd", "type": "textarea"}]', '{"required": true, "label": "3×4 ölçülü fotoşəkil", "accept": "image", "max": 1}', '["Dekanlıq yoxlayır", "Bilet hazırlanır"]', '', 0, '["office", "office"]', 'none'),
('absence_excuse', 3, 'attendance', 'Qayıbın üzrlü hesab edilməsi', 'heart', 48, NULL, NULL, 'QYB', 'Xəstəlik və ya digər üzrlü səbəbə görə buraxılmış dərslər üçün. Təsdiqedici sənədi (məs., həkim arayışı) yükləyin.', '["Həkim arayışı və ya digər təsdiqedici sənəd (PDF, JPG, PNG)"]', 'Seçilmiş qayıblar elektron jurnalda “üzrlü” kimi qeyd olunur, fənn müəllimlərinə bildiriş gedir.', 'Tibbi sənədləri yalnız dekanlıq görür. Müəllimlər yalnız qayıbın “üzrlü” statusunu görür.', '[{"name": "reason", "label": "Səbəb", "type": "radio", "required": true, "options": ["Xəstəlik", "Ailə vəziyyəti", "Rəsmi tədbir (olimpiada, yarış, konfrans)", "Digər"]}, {"name": "period", "label": "Dövr", "type": "daterange", "required": true}, {"name": "absences", "label": "Üzrlü hesab ediləcək dərslər", "type": "absences", "required": true}, {"name": "details", "label": "Əlavə izah", "type": "textarea", "placeholder": "İstəyə görə"}]', '{"required": true, "label": "Təsdiqedici sənəd (həkim arayışı və s.)", "accept": "doc", "max": 3}', '["Dekanlıq sənədi yoxlayır", "Davamiyyət jurnalında qeyd olunur"]', 'Təqdim etdiyiniz sənəd əsasında seçilmiş dərslərdəki qayıblar üzrlü hesab edildi. Fənn müəllimlərinə bildiriş göndərildi.', 1, '["office", "office"]', 'attendance.excuse'),
('leave_permission', 4, 'attendance', 'Dərslərdən icazə (əvvəlcədən)', 'calcheck', 48, NULL, NULL, 'İCZ', 'Olimpiada, idman yarışı, konfrans və ya digər səbəbdən dərslərə gəlməyəcəyinizi əvvəlcədən bildirin.', '["Dəvətnamə və ya təsdiqedici sənəd (varsa)"]', 'İcazə təsdiqlənəndə seçilmiş fənlərin müəllimləri avtomatik məlumatlandırılır.', '', '[{"name": "reason", "label": "Səbəb", "type": "radio", "required": true, "options": ["Olimpiada / müsabiqə", "İdman yarışı", "Konfrans / elmi tədbir", "Ailə tədbiri", "Planlı müalicə", "Digər"]}, {"name": "period", "label": "Dövr", "type": "daterange", "required": true, "future": true}, {"name": "courses", "label": "Buraxılacaq fənlər", "type": "courses", "required": true}, {"name": "details", "label": "İzah", "type": "textarea", "required": true, "placeholder": "Məsələn: Bakı şəhər proqramlaşdırma olimpiadasında iştirak"}]', '{"required": false, "label": "Dəvətnamə və ya təsdiqedici sənəd", "accept": "doc", "max": 3}', '["Dekanlıq baxır", "Müəllimlərə bildiriş göndərilir"]', '', 0, '["office", "office"]', 'none'),
('exam_reschedule', 5, 'attendance', 'İmtahanın başqa vaxta keçirilməsi', 'clock', 72, NULL, NULL, 'İMT', 'Üzrlü səbəbdən kollokvium, imtahan və ya laboratoriya işinin müdafiəsində iştirak edə bilmədikdə.', '["Səbəbi təsdiq edən sənəd"]', 'Yeni tarix kafedra ilə razılaşdırılaraq sizə bildiriləcək.', '', '[{"name": "course", "label": "Fənn", "type": "course", "required": true}, {"name": "exam_type", "label": "Qiymətləndirmə növü", "type": "select", "options": ["Kollokvium", "Semestr imtahanı", "Laboratoriya işinin müdafiəsi"]}, {"name": "exam_date", "label": "İmtahanın tarixi", "type": "date", "required": true}, {"name": "reason", "label": "Səbəb", "type": "radio", "required": true, "options": ["Xəstəlik", "Rəsmi tədbir", "Digər"]}, {"name": "details", "label": "İzah", "type": "textarea"}]', '{"required": true, "label": "Təsdiqedici sənəd", "accept": "doc", "max": 3}', '["Dekanlıq baxır", "Kafedra ilə razılaşdırılır", "Yeni tarix təyin olunur"]', '', 0, '["office", "dept_head", "office"]', 'none'),
('academic_leave', 6, 'academic', 'Akademik məzuniyyət', 'pause', 72, 'AKADEMİK MƏZUNİYYƏT HAQQINDA ƏMRDƏN ÇIXARIŞ', 'EXTRACT FROM THE ORDER ON ACADEMIC LEAVE', 'AKM', 'Səhhət, ailə vəziyyəti, hərbi xidmət və digər üzrlü səbəblərə görə təhsilə müvəqqəti fasilə.', '["Səbəbi təsdiq edən sənəd"]', 'Rektorun əmrindən QR kodlu elektron çıxarış.', '', '[{"name": "reason", "label": "Səbəb", "type": "select", "required": true, "options": ["Səhhət", "Ailə vəziyyəti", "Hərbi xidmət", "Digər"]}, {"name": "period", "label": "Müddət", "type": "select", "options": ["1 semestr", "1 tədris ili"]}, {"name": "start", "label": "Başlanğıc", "type": "select", "options": ["2026/2027 payız semestri", "2026/2027 yaz semestri"]}, {"name": "details", "label": "Ətraflı izah", "type": "textarea", "required": true}]', '{"required": true, "label": "Səbəbi təsdiq edən sənəd", "accept": "doc", "max": 3}', '["Dekanlıqda baxılır", "Tədris hissəsində yoxlanılır", "Əmr hazırlanır və təsdiqlənir"]', '', 0, '["office", "academic_office", "academic_office"]', 'student_status.leave'),
('grade_appeal', 7, 'academic', 'Qiymətləndirmə nəticəsinə apellyasiya', 'scale', 72, NULL, NULL, 'APL', 'Kollokvium, imtahan və ya test nəticəsi ilə razı olmadıqda.', '["Əsaslandırma; varsa, əlavə sənəd"]', 'Apellyasiya komissiyasının qərarı bildiriləcək.', '', '[{"name": "course", "label": "Fənn", "type": "course", "required": true}, {"name": "exam_type", "label": "Qiymətləndirmə", "type": "select", "options": ["Kollokvium 1", "Kollokvium 2", "Semestr imtahanı", "Test"]}, {"name": "score", "label": "Aldığınız bal", "type": "number", "min": 0, "max": 100}, {"name": "details", "label": "Apellyasiyanın əsası", "type": "textarea", "required": true}]', '{"required": false, "label": "Əlavə sənəd", "accept": "doc", "max": 3}', '["Dekanlıq qəbul edir", "Apellyasiya komissiyası baxır", "Qərar bildirilir"]', '', 0, '["office", "academic_office", "office"]', 'none'),
('individual_plan', 8, 'academic', 'Fərdi tədris qrafiki', 'calendar', 120, NULL, NULL, 'FTQ', 'İşləyən, peşəkar idmançı, valideyn olan və ya səhhəti ilə bağlı fərdi qrafikə ehtiyacı olan tələbələr üçün.', '["Təsdiqedici sənəd (iş yerindən arayış və s.)"]', 'Təsdiqlənmiş fərdi qrafik müəllimlərlə razılaşdırılaraq profilinizə əlavə olunur.', '', '[{"name": "reason", "label": "Əsas", "type": "radio", "required": true, "options": ["İşləyirəm", "Peşəkar idmançıyam", "Səhhət", "Valideynəm", "Digər"]}, {"name": "semester", "label": "Semestr", "type": "select", "options": ["2026/2027 payız semestri", "2026/2027 yaz semestri"]}, {"name": "details", "label": "İzah", "type": "textarea", "required": true}]', '{"required": true, "label": "Təsdiqedici sənəd", "accept": "doc", "max": 3}', '["Dekanlıq baxır", "Müəllimlərlə razılaşdırılır", "Fərdi qrafik təsdiqlənir"]', '', 0, '["office", "office", "office"]', 'none'),
('tuition_installment', 9, 'finance', 'Təhsil haqqının hissə-hissə ödənilməsi', 'wallet', 72, NULL, NULL, 'THH', 'Ödənişli əsaslarla təhsil alan tələbələr üçün ödəniş qrafiki.', '["Əsaslandırma"]', 'Təsdiqlənmiş ödəniş qrafiki.', '', '[{"name": "parts", "label": "Hissələrin sayı", "type": "select", "options": ["2 hissə", "3 hissə", "4 hissə"]}, {"name": "details", "label": "Səbəb", "type": "textarea", "required": true}]', '{"required": false, "label": "Əlavə sənəd", "accept": "doc", "max": 2}', '["Maliyyə şöbəsi baxır", "Ödəniş qrafiki təsdiqlənir"]', '', 0, '["academic_office", "academic_office"]', 'none'),
('social_scholarship', 10, 'finance', 'Sosial təqaüd üçün müraciət', 'heart', 120, NULL, NULL, 'STQ', 'Qanunvericilikdə nəzərdə tutulmuş kateqoriyalara aid tələbələr üçün.', '["Kateqoriyanı təsdiq edən sənəd"]', 'Təqaüd komissiyasının qərarı bildiriləcək.', 'Sənədlər yalnız dekanlıq və təqaüd komissiyası tərəfindən görülür.', '[{"name": "category", "label": "Kateqoriya", "type": "select", "required": true, "options": ["Valideyn himayəsindən məhrum", "Sağlamlıq imkanları məhdud", "Şəhid ailəsinin üzvü", "Aztəminatlı ailə", "Digər"]}, {"name": "details", "label": "Əlavə məlumat", "type": "textarea"}]', '{"required": true, "label": "Təsdiqedici sənəd", "accept": "doc", "max": 3}', '["Dekanlıq sənədləri yoxlayır", "Təqaüd komissiyası baxır"]', '', 0, '["office", "academic_office"]', 'none'),
('dormitory', 11, 'campus', 'Yataqxanada yer', 'building', 120, NULL, NULL, 'YTQ', 'Bölgələrdən gələn və sosial müdafiəyə ehtiyacı olan tələbələrə üstünlük verilir.', '["Daimi yaşayış yeri haqqında məlumat"]', 'Yer ayrıldıqda bildiriş və yataqxana ünvanı.', '', '[{"name": "city", "label": "Daimi yaşayış yeri (şəhər / rayon)", "type": "text", "required": true}, {"name": "basis", "label": "Əsas", "type": "select", "options": ["Bölgədən gəlmişəm", "Sosial müdafiəyə ehtiyacım var", "Digər"]}, {"name": "details", "label": "Əlavə qeyd", "type": "textarea"}]', '{"required": false, "label": "Əlavə sənəd", "accept": "doc", "max": 2}', '["Tələbə xidmətləri baxır", "Yer ayrılır"]', '', 0, '["office", "office"]', 'none'),
('free_application', 12, 'other', 'Sərbəst ərizə', 'edit', 72, NULL, NULL, 'ƏRZ', 'Siyahıda olmayan istənilən məsələ üzrə dekanlığa, tədris hissəsinə və ya rektorluğa müraciət.', '[]', 'Yazılı cavab.', '', '[{"name": "to", "label": "Kimə", "type": "select", "options": ["Dekanlıq", "Tədris hissəsi", "Rektorluq", "Tələbə xidmətləri mərkəzi"]}, {"name": "subject", "label": "Mövzu", "type": "text", "required": true}, {"name": "body", "label": "Ərizənin mətni", "type": "textarea", "required": true}]', '{"required": false, "label": "Əlavə sənəd", "accept": "doc", "max": 3}', '["Baxılır və cavablandırılır"]', '', 0, '["office"]', 'none')
